const initials = (name: string) => name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase()

export default function UseCaseDetail() {
  const { company_slug, title_slug } = useParams<{ company_slug: string; title_slug: string }>()
  const navigate = useNavigate()
  const { user } = useAuth()
  const [useCase, setUseCase] = useState<DetailedUseCase | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [openDropdown, setOpenDropdown] = useState(false)
  const [deleteModalOpen, setDeleteModalOpen] = useState(false)
  const [bookmarked, setBookmarked] = useState(false)
  const [bookmarkCount, setBookmarkCount] = useState<number | null>(null)

  const fetchUseCaseDetail = async () => {
    if (!company_slug || !title_slug) {
      setError("Use case route is incomplete.")
      setLoading(false)
      return
    }
    try {
      setLoading(true)
      setError(null)
      const response = await fetch(buildApiUrl(`/api/v1/use-cases/${company_slug}/${title_slug}`), { credentials: "include" })
      if (!response.ok) throw new Error("Failed to fetch use case details.")
      const data = await response.json() as DetailedUseCase
      setUseCase(data)
      setBookmarkCount(data.saves ?? null)
      window.scrollTo(0, 0)
      void useCasesApi.bookmarks().then((saved) => {
        const currentId = String(data._id || data.id || "")
        setBookmarked(saved.some((item) => String(item.id) === currentId))
